function checkValidGrid(grid: number[][]): boolean {
    if (grid[0][0] !== 0) {
        return false;
    }
    const n = grid.length;
    const pos = Array.from(new Array(n * n), () => new Array(2).fill(0));
    for (let i = 0; i < n; ++i) {
        for (let j = 0; j < n; ++j) {
            pos[grid[i][j]] = [i, j];
        }
    }
    for (let i = 1; i < n * n; ++i) {
        const p1 = pos[i - 1];
        const p2 = pos[i];
        const dx = Math.abs(p1[0] - p2[0]);
        const dy = Math.abs(p1[1] - p2[1]);
        const ok = (dx === 1 && dy === 2) || (dx === 2 && dy === 1);
        if (!ok) {
            return false;
        }
    }
    return true;
}

//Editorial: https://leetcode.com/problems/check-knight-tour-configuration/solutions/3314113/bruteforce-very-simple-easy-to-understand-solution/?orderBy=most_votes
class Solution {
public:
    vector<vector<int>> dir={{-1,2},{-1,-2},{-2,-1},{-2,1},{1,2},{1,-2},{2,-1},{2,1}};
    bool checkValidGrid(vector<vector<int>>& grid) {
        int m=grid.size();
        int n=grid[0].size();
        int cnt=0,maxcnt=m*n-1;
        if(grid[0][0]!=0)
            return false;
        int x=0,y=0;
        while(cnt<maxcnt)
        {
            cnt+=1;
            int i,j;
            int f=0;
            for(auto it:dir)
            {
                i=x+it[0];
                j=y+it[1];
                if(i>=0 and i<m and j>=0 and j<n and grid[i][j]==cnt)
                {
                    x=i;
                    y=j;
                    f=1;
                    break;
                }
            }
            if(!f)
                return false;
        }
        return true;
    }
};

class Solution(object):
    def checkValidGrid(self, grid):
        """
        :type grid: List[List[int]]
        :rtype: bool
        """
        if grid[0][0] != 0:
            return False
        n = len(grid)
        indices = {}
        for i in range(n):
            for j in range(n):
                indices[grid[i][j]] = (i, j)
        for i in range(1, n * n):
            dx = abs(indices[i][0] - indices[i - 1][0])
            dy = abs(indices[i][1] - indices[i - 1][1])
            if dx * dy != 2:
                return False
        return True
